def decode_shift(s: str) -> str:
    """
    Takes a string encoded with `encode_shift` and returns the original string
    by shifting each character back by 5 positions in the alphabet.
    """
    # Reverse the shift: subtract 5 and wrap around the alphabet.
    return "".join(
        chr(((ord(ch) - 5 - ord("a")) % 26) + ord("a")) for ch in s
