def encode(text: str) -> str:
    """Encode the string by rotating each 3‑character chunk left by one."""
    return ''.join(
        chunk[1:] + chunk[0] if len(chunk) == 3 else chunk
        for chunk in (text[i:i+3] for i in range(0, len(text), 3))
    )

def decode(text: str) -> str:
    """Decode the string by rotating each 3‑character chunk right by one."""
    return ''.join(
        chunk[-1] + chunk[:-1] if len(chunk) == 3 else chunk
        for chunk in (text[i:i+3] for i in range(0, len(text), 3))
    )

if __name__ == "__main__":
    sample = "HelloWorld"
    encoded = encode(sample)
    decoded = decode(encoded)
    print(f"Original: {sample}")
    print(f"Encoded : {encoded}")
    print(f"Decoded : {decoded}")
