def compare_numeric_inputs(a, b):
    """
    Compare two numeric inputs by converting them to float after replacing commas with dots.
    Return None if equal, otherwise return the input with the higher numeric value.
    """
    # Helper function to normalize string input to float
    def to_float(value):
        if isinstance(value, (int, float)):
            return float(value)
        # Replace comma with dot and convert to float
        return float(str(value).replace(',', '.'))

    try:
        float_a = to_float(a)
        float_b = to_float(b)

        if float_a == float_b:
            return None
        elif float_a > float_b:
            return a
        else:
            return b
    except (ValueError, TypeError):
        # Handle invalid numeric inputs gracefully
        raise ValueError("Invalid numeric input")

